bomData.valueScript:
// HOMAG Standard Bom-Generation-Method
//=================================================

// Type of the Bom-Element (will be checked in order output)
const elementType='Board';

// ProductionSite Category (to split the orders for different production sites)
const elementCategory='';

// Id of the parent to create the hierarchy
const parentBomId=part.pa_BomId;

// Mode from basic setting
const Mode = partSelf._g?.basic_CreateBom  ? partSelf._g.basic_CreateBom : 'SimpleBoard';

// Call the function to process the Bom-Element
GlobalFunc.process_BomGeneration(this, part, elementType, elementCategory, parentBomId, Mode, 'Carcase');

ncData.valueScript:
//====================================================================
  // Validate processing ID
  //====================================================================

  const processingId = part2.pa_ProcessingId?.trim();
  if (!processingId || processingId.toLowerCase() === 'n/a') {
    return;
  }

  //====================================================================
  // Get drilling information
  //====================================================================

  const drillVertId = GlobalFunc.find_ProcessingMapping(processingId)?.[0]?.ProcessingId ?? '';
  const drillInfo = GlobalFunc.find_HardwareDrillVertLibrary(drillVertId, 'ShelfAdj')?.[0];

  if (!drillInfo) {
    return;
  }

  //====================================================================
  // Determine drill position
  //====================================================================

  type ShelfDrillSide = 'Left' | 'Right' | 'Front' | 'Back';
  const tolerance = 30;
  let drillSide: ShelfDrillSide;

  if (posRel.x < tolerance) {
    drillSide = 'Left';
  }
  else if (posRel.x > partSelf._dimx - tolerance) {
    drillSide = 'Right';
  }
  else if (posRel.z < tolerance) {
    drillSide = 'Back';
  }
  else {
    drillSide = 'Front';
  }

  const offset = drillInfo.XA ?? 0;
  const positions: Record<ShelfDrillSide, { x: number; y: number }> = {
    Left:  { x: offset,                    y: posRel.z },
    Right: { x: partSelf._dimx - offset,   y: posRel.z },
    Front: { x: posRel.x,                  y: partSelf._dimz - offset },
    Back:  { x: posRel.x,                  y: offset }
  };
  const { x: posX, y: posY } = positions[drillSide];

  //====================================================================
  // Add vertical drilling
  //====================================================================

  const drill = this.addncout_DrillVert();

  drill.nc_TOOL = '102';
  drill.nc_XA = posX;
  drill.nc_YA = posY;
  drill.nc_TI = drillInfo.TI;
  drill.nc_DU = drillInfo.DU;
  drill.nc_Side = 'Btm';

  drill.nc_BM = drillInfo.matrix_BM || 'LS';
  drill.nc_WI = drillInfo.matrix_WI ?? 0;
  drill.nc_AB = drillInfo.matrix_AB ?? 1;
  drill.nc_LA = drillInfo.matrix_LA ?? 0;
  drill.nc_MI = drillInfo.matrix_MI ?? 0;
  drill.nc_KO = drillInfo.matrix_KO || '00';

  //====================================================================
  // Add visual drilling
  //====================================================================

  const drilling3D = partSelf.add3DElement('ShelfAdjPinDrilling', drill,
    posX, 0, posY,
    drillInfo.DU, drillInfo.TI, drillInfo.DU
  );

  drilling3D.extrude(`<svg><circle cx="0" cy="0" r="${drillInfo.DU / 2}" /></svg>`, 'y');
